package com.tapeverify.copilot.service;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.tapeverify.copilot.dto.*; import com.tapeverify.copilot.entity.*; import com.tapeverify.copilot.repository.AuditLogRepository; import java.time.LocalDateTime; import java.util.List; import org.springframework.stereotype.Service;
@Service public class AuditServiceImpl implements AuditService { private final AuditLogRepository repository; private final ObjectMapper objectMapper; public AuditServiceImpl(AuditLogRepository repository,ObjectMapper objectMapper){this.repository=repository;this.objectMapper=objectMapper;} public void record(Loan loan,AuditAction action,String user,String oldHash,AuditLoanSnapshotDto oldDetails){repository.save(AuditLog.builder().loan(loan).action(action).modifiedBy(user==null||user.isBlank()?"system":user).oldHash(oldHash).newHash(loan.getSha256Hash()).oldDetails(write(oldDetails)).newDetails(write(AuditLoanSnapshotDto.from(loan))).timestamp(LocalDateTime.now()).build());} public List<AuditLogDto> history(Long loanId){return repository.findByLoanIdOrderByTimestampAsc(loanId).stream().map(a->AuditLogDto.builder().id(a.getId()).action(a.getAction().name()).modifiedBy(a.getModifiedBy()).oldDetails(read(a.getOldDetails())).newDetails(read(a.getNewDetails())).timestamp(a.getTimestamp()).build()).toList();} private String write(AuditLoanSnapshotDto value){if(value==null)return null;try{return objectMapper.writeValueAsString(value);}catch(JsonProcessingException e){throw new IllegalStateException("Could not write audit snapshot",e);}} private AuditLoanSnapshotDto read(String value){if(value==null||value.isBlank())return null;try{return objectMapper.readValue(value,AuditLoanSnapshotDto.class);}catch(JsonProcessingException e){throw new IllegalStateException("Could not read audit snapshot",e);}} }
